package osal

// Native inputs of this package. OSAL_CFLAGS comes from the demo's build.sh
// (absolute path resolved at build time, make-artifact.sh style); the C
// files compile with the target's C compiler. The link inputs live in
// link_args.go, also generated by build.sh - LLGoPackage expands env-var
// references into a single argv element, so the archive and linker-script
// paths must be baked in at generation time.

const LLGoFiles = "$OSAL_CFLAGS: _wrap/osi_osal.c; _wrap/osal_intr.c; _wrap/wifi_api.c; _wrap/wifi_regulatory.c; _wrap/ftm_calibration.c"
